{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or replace table snitch_db.maplemonk.offline_metafield_normalized_str as WITH mapped AS ( SELECT branch_code, marketplace_mapped AS store_name, COALESCE(new_category, \'No_CATEGORY\') AS category, CASE WHEN UPPER(COALESCE(new_category,\'\')) LIKE \'%T-SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'GRAPHIC PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Self Design & Textured\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'FLORAL\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TIE & DYE\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'PRINTED\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'GEOMETRIC\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'ANIMAL PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroided\' ELSE \'Others\' END WHEN UPPER(COALESCE(new_category,\'\')) LIKE \'%SHIRTS%\' THEN CASE WHEN style ILIKE \'%Linen%\' THEN \'Linen\' WHEN style ILIKE \'%Luxe%\' THEN \'Snitch LUXE\' WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Self Design & Textured\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) IN (\'PRINTED\',\'FLORAL\',\'GEOMETRIC\',\'TIE & DYE\',\'GRAPHIC PRINT\',\'ANIMAL PRINT\') THEN \'Printed\' WHEN UPPER(TRIM(designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroided\' ELSE \'Others\' END ELSE designs END AS designs_new, CASE WHEN UPPER(COALESCE(new_category,\'\')) LIKE \'%T-SHIRTS%\' THEN CASE WHEN TRIM(LOWER(collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(collar_new)) = \'polo\' THEN \'Polo\' ELSE \'Others\' END ELSE NULL END AS collar_new_std, COALESCE(fit,\'No_fit\') AS fit, opening_inventory_7d, closing_inventory_7d, sales_qty_7d, opening_inventory_15d, closing_inventory_15d, sales_qty_15d, opening_inventory_30d, closing_inventory_30d, sales_qty_30d FROM snitch_db.maplemonk.offline_metafield_str ), meta_base AS ( SELECT branch_code, store_name, category, CASE WHEN UPPER(category) IN (\'TROUSERS\',\'JEANS\') THEN COALESCE(fit, \'No_fit\') WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN COALESCE(collar_new_std, \'Others\') WHEN UPPER(category) in (\'SHIRTS\') THEN COALESCE(designs_new, \'Other\') ELSE category END AS meta1, CASE WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN COALESCE(designs_new, \'Others\') ELSE \'N/A\' END AS meta2, opening_inventory_7d, closing_inventory_7d, sales_qty_7d, opening_inventory_15d, closing_inventory_15d, sales_qty_15d, opening_inventory_30d, closing_inventory_30d, sales_qty_30d FROM mapped ) SELECT branch_code, store_name, category, meta1, meta2, ROUND( 100 * SUM(sales_qty_7d) / NULLIF( (SUM(opening_inventory_7d) + SUM(closing_inventory_7d)) / 2.0, 0 ), 2 ) AS str_7d_pct, ROUND( 100 * SUM(sales_qty_15d) / NULLIF( (SUM(opening_inventory_15d) + SUM(closing_inventory_15d)) / 2.0, 0 ), 2 ) AS str_15d_pct, ROUND( 100 * SUM(sales_qty_30d) / NULLIF( (SUM(opening_inventory_30d) + SUM(closing_inventory_30d)) / 2.0, 0 ), 2 ) AS str_30d_pct FROM meta_base GROUP BY branch_code, store_name, category, meta1, meta2 HAVING SUM(sales_qty_30d) > 0 OR (SUM(opening_inventory_30d) + SUM(closing_inventory_30d)) > 0 ORDER BY branch_code, category, meta1, meta2; create or replace table snitch_db.maplemonk.offline_metafield_delta as WITH store_map AS ( SELECT DISTINCT BRANCH_CODE AS Branch_code, MARKETPLACE_MAPPED AS Store_name, STATE AS STATE, AM AS AREA_MANAGER FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ), metafields_std AS ( SELECT om.sku_group, MAX(om.new_category) AS category, MAX(CASE WHEN UPPER(om.new_category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN UPPER(TRIM(om.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(om.designs)) = \'GRAPHIC PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'TEXTURED\' THEN \'Self Design & Textured\' WHEN UPPER(TRIM(om.designs)) = \'SELF DESIGN\' THEN \'Self Design & Textured\' WHEN UPPER(TRIM(om.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(om.designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(om.designs)) = \'PRINTED\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(om.designs)) = \'GEOMETRIC\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(om.designs)) = \'FLORAL\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'TIE & DYE\' THEN \'Graphic Print\' WHEN UPPER(TRIM(om.designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(om.designs)) = \'ANIMAL PRINT\' THEN \'Graphic Print\' ELSE \'Others\' END WHEN UPPER(om.new_category) LIKE \'%SHIRTS%\' THEN CASE WHEN om.style ILIKE \'%Linen%\' THEN \'Linen\' WHEN om.style ILIKE \'%Luxe%\' THEN \'Snitch LUXE\' WHEN UPPER(TRIM(om.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(om.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(om.designs)) = \'TEXTURED\' THEN \'Self Design & Textured\' WHEN UPPER(TRIM(om.designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(om.designs)) = \'SELF DESIGN\' THEN \'Self Design & Textured\' WHEN UPPER(TRIM(om.designs)) = \'PRINTED\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(om.designs)) = \'FLORAL\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(om.designs)) = \'GEOMETRIC\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'TIE & DYE\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(om.designs)) = \'GRAPHIC PRINT\' THEN \'Printed\' WHEN UPPER(TRIM(om.designs)) = \'ANIMAL PRINT\' THEN \'Printed\' ELSE \'Others\' END ELSE om.designs END) AS designs_new, MAX(CASE WHEN UPPER(om.new_category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN TRIM(LOWER(om.collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(om.collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(om.collar_new)) = \'polo\' THEN \'Polo\' ELSE \'Others\' END ELSE NULL END) AS collar_new_std FROM snitch_db.maplemonk.offline_master om GROUP BY 1 ), size_health AS ( SELECT sku_group, branch_code, CASE WHEN UPPER(sku_group) LIKE \'4MBG%\' AND ( (CASE WHEN XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS > 0 THEN 1 ELSE 0 END) ) >= 4 THEN 1 WHEN UPPER(sku_group) NOT LIKE \'4MBG%\' AND ( (CASE WHEN S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS > 0 THEN 1 ELSE 0 END) ) >= 4 THEN 1 ELSE 0 END AS is_full_size_store, CASE WHEN (inventory = 0) AND UPPER(sku_group) LIKE \'4MBG%\' AND ( (CASE WHEN JIT_XS_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_2XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_3XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_4XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_5XL_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_6XL_UNITS > 0 THEN 1 ELSE 0 END) ) >= 4 THEN 1 WHEN (inventory = 0) AND UPPER(sku_group) NOT LIKE \'4MBG%\' AND ( (CASE WHEN JIT_S_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_M_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_L_UNITS > 0 THEN 1 ELSE 0 END) + (CASE WHEN JIT_XL_UNITS > 0 THEN 1 ELSE 0 END) ) >= 4 THEN 1 ELSE 0 END AS is_full_size_transit FROM snitch_db.maplemonk.offline_master WHERE (inventory + jit_qty) > 0 ), base AS ( SELECT om.Branch_code, COALESCE(om.new_CATEGORY, \'No_CATEGORY\') AS CATEGORY, CASE WHEN UPPER(COALESCE(om.new_CATEGORY, \'\')) IN (\'TROUSERS\',\'JEANS\') THEN COALESCE(om.fit, \'No_fit\') WHEN UPPER(COALESCE(om.new_CATEGORY, \'\')) LIKE \'%T-SHIRTS%\' THEN COALESCE(ms.collar_new_std, \'Others\') WHEN UPPER(COALESCE(om.new_CATEGORY, \'\')) LIKE \'%SHIRTS%\' THEN COALESCE(ms.designs_new, \'Other\') ELSE COALESCE(om.new_CATEGORY, \'No_CATEGORY\') END AS META1, CASE WHEN UPPER(COALESCE(om.new_CATEGORY, \'\')) LIKE \'%T-SHIRTS%\' THEN COALESCE(ms.designs_new, \'Others\') ELSE \'N/A\' END AS META2, SUM(COALESCE(om.SALES_LAST_7_DAYS, 0)) AS SALES_7D, SUM(COALESCE(om.SALES_LAST_15_DAYS, 0)) AS SALES_15D, SUM(COALESCE(om.SALES_LAST_30_DAYS, 0)) AS SALES_30D, SUM(COALESCE(om.Inventory, 0) + COALESCE(om.JIT_QTY, 0)) AS INV_UNITS, SUM(COALESCE(sh.is_full_size_store, 0)) AS FULL_SIZE_STORE_COUNT, SUM(COALESCE(sh.is_full_size_transit, 0)) AS FULL_SIZE_TRANSIT_COUNT, COUNT(om.sku_group) AS TOTAL_OPTIONS_COUNT, MAX(om.base_stock) AS STORE_BASE_STOCK, MAX(om.dept_ideal) AS DEPTH_VAL FROM snitch_db.maplemonk.offline_master om LEFT JOIN metafields_std ms ON om.sku_group = ms.sku_group LEFT JOIN size_health sh ON om.sku_group = sh.sku_group AND om.branch_code = sh.branch_code GROUP BY 1,2,3,4 ), totals AS ( SELECT b.*, SUM(b.SALES_7D) OVER (PARTITION BY b.Branch_code) AS STORE_SALES_7D, SUM(b.SALES_15D) OVER (PARTITION BY b.Branch_code) AS STORE_SALES_15D, SUM(b.SALES_30D) OVER (PARTITION BY b.Branch_code) AS STORE_SALES_30D, SUM(b.INV_UNITS) OVER (PARTITION BY b.Branch_code) AS STORE_INV_UNITS, MAX(b.STORE_BASE_STOCK) OVER (PARTITION BY b.Branch_code) AS FINAL_STORE_BASE_STOCK FROM base b ), metrics AS ( SELECT t.*, ROUND(100 * t.SALES_7D / NULLIF(t.STORE_SALES_7D, 0), 2) AS SALES_MIX_7D_PCT, ROUND(100 * t.SALES_15D / NULLIF(t.STORE_SALES_15D, 0), 2) AS SALES_MIX_15D_PCT, ROUND(100 * t.SALES_30D / NULLIF(t.STORE_SALES_30D, 0), 2) AS SALES_MIX_30D_PCT, ROUND(100 * t.INV_UNITS / NULLIF(t.STORE_INV_UNITS, 0), 2) AS INV_MIX_PCT, str.str_7d_pct AS STR_7D_PCT, str.str_15d_pct AS STR_15D_PCT, str.str_30d_pct AS STR_30D_PCT FROM totals t LEFT JOIN snitch_db.maplemonk.OFFLINE_METAFIELD_NORMALIZED_STR str ON t.branch_code = str.branch_code AND UPPER(TRIM(t.category)) = UPPER(TRIM(str.category)) AND UPPER(TRIM(t.meta1)) = UPPER(TRIM(str.meta1)) AND UPPER(TRIM(t.meta2)) = UPPER(TRIM(str.meta2)) ), final_metrics AS ( SELECT m.*, ROUND( 0.5 * COALESCE(m.STR_7D_PCT, 0) + 0.3 * COALESCE(m.STR_15D_PCT, 0) + 0.2 * COALESCE(m.STR_30D_PCT, 0), 2 ) AS OPPORTUNITY_STR_PCT, ROUND( 0.5 * COALESCE(m.SALES_MIX_7D_PCT, 0) + 0.3 * COALESCE(m.SALES_MIX_15D_PCT, 0) + 0.2 * COALESCE(m.SALES_MIX_30D_PCT, 0), 2 ) AS OPPORTUNITY_SALES_MIX_PCT FROM metrics m ) SELECT f.Branch_code, sm.Store_name, SM.STATE, SM.AREA_MANAGER, f.CATEGORY, f.META1, f.META2, f.SALES_7D, f.SALES_15D, f.SALES_30D, f.INV_UNITS, f.SALES_MIX_7D_PCT, f.SALES_MIX_15D_PCT, f.SALES_MIX_30D_PCT, f.STR_7D_PCT, f.STR_15D_PCT, f.STR_30D_PCT, f.OPPORTUNITY_STR_PCT, f.final_store_base_stock AS base_stock, idl.cat_mix, idl.meta_mix_pct, CEIL((COALESCE(f.FINAL_STORE_BASE_STOCK, 0) * (COALESCE(idl.metafield_ideal_mix, 0) / 100.0)) / NULLIF(f.DEPTH_VAL, 0)) AS IDEAL_OPTIONS, f.FULL_SIZE_STORE_COUNT AS ACTUAL_FULL_SIZE_STORE, f.FULL_SIZE_TRANSIT_COUNT AS ACTUAL_FULL_SIZE_TRANSIT, f.OPPORTUNITY_SALES_MIX_PCT, f.INV_MIX_PCT, COALESCE(idl.metafield_ideal_mix, 0) AS IDEAL_MIX_PCT, CASE WHEN (f.OPPORTUNITY_SALES_MIX_PCT > f.INV_MIX_PCT) AND (f.OPPORTUNITY_SALES_MIX_PCT < idl.metafield_ideal_mix) THEN \'Allocate\' WHEN (f.OPPORTUNITY_SALES_MIX_PCT > f.INV_MIX_PCT) AND (f.OPPORTUNITY_SALES_MIX_PCT > idl.metafield_ideal_mix) THEN \'Allocate and Redefine\' WHEN (f.OPPORTUNITY_SALES_MIX_PCT < f.INV_MIX_PCT) AND (f.INV_MIX_PCT > idl.metafield_ideal_mix) THEN \'RTV\' WHEN (f.OPPORTUNITY_SALES_MIX_PCT < f.INV_MIX_PCT) AND (f.INV_MIX_PCT < idl.metafield_ideal_mix) THEN \'Review\' ELSE \'Review\' END AS INVENTORY_ACTION_ITEM, ROUND( COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0), 2 ) AS DELTA_PCT, CEIL( CASE WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 3 THEN GREATEST( GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ), COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (3.0/100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) ) WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 1 AND (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) < 3 THEN GREATEST( GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ), COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (1.0/100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) ) WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 0 AND (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) <= 1 THEN GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ) ELSE 0 END ) AS OPTIONS_TO_ALLOCATE, ( CEIL( CASE WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 3 THEN GREATEST( GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ), COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (3.0/100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) ) WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 1 AND (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) < 3 THEN GREATEST( GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ), COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (1.0/100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) ) WHEN (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) > 0 AND (COALESCE(f.OPPORTUNITY_SALES_MIX_PCT,0) - COALESCE(f.INV_MIX_PCT,0)) <= 1 THEN GREATEST( 0, COALESCE( CEIL( (COALESCE(f.FINAL_STORE_BASE_STOCK,0) * (COALESCE(idl.metafield_ideal_mix,0) / 100.0)) / NULLIF(f.DEPTH_VAL,0) ), 0 ) - COALESCE(f.FULL_SIZE_STORE_COUNT + f.FULL_SIZE_TRANSIT_COUNT,0) ) ELSE 0 END ) * COALESCE(f.DEPTH_VAL,0) ) AS QTY_TO_ALLOCATE FROM final_metrics f LEFT JOIN store_map sm ON f.Branch_code = sm.Branch_code LEFT JOIN snitch_db.maplemonk.offline_metafield_ideal_mix idl ON f.Branch_code = idl.branch_code AND UPPER(TRIM(f.CATEGORY)) = UPPER(TRIM(idl.category)) AND ( CASE WHEN UPPER(f.CATEGORY) LIke \'%T-SHIRTS%\' THEN UPPER(TRIM(f.META1)) = UPPER(TRIM(idl.meta_1)) AND UPPER(TRIM(f.META2)) = UPPER(TRIM(idl.meta_2)) WHEN UPPER(f.CATEGORY) in (\'SHIRTS\') OR UPPER(f.CATEGORY) IN (\'TROUSERS\',\'JEANS\') THEN UPPER(TRIM(f.META1)) = UPPER(TRIM(idl.meta_1)) ELSE TRUE END ) WHERE (f.STORE_SALES_30D > 0 OR f.STORE_INV_UNITS > 0) AND f.CATEGORY NOT IN (\'Bags\',\'Belts\',\'Shoes\',\'Sunglasses\') AND idl.cat_mix IS NOT NULL ORDER BY f.Branch_code, f.OPPORTUNITY_STR_PCT DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            